const retrieveReferenceNumbers = () => {
    let referenceNumber = null;
    let referenceNumbers = [];
    if (localStorage.getItem("referenceNumbers")) {
        referenceNumbers = JSON.parse(localStorage.getItem("referenceNumbers"));
        referenceNumber = referenceNumbers.shift()
        console.log("The one ref num", referenceNumber);

        localStorage.removeItem("referenceNumbers");
        localStorage.setItem("referenceNumbers", JSON.stringify(referenceNumbers));
        return referenceNumber
    } else {
        return null;
    }
};


